
let produtos = JSON.parse(localStorage.getItem("produtos")) || [];

let proximoCodigo = produtos.length > 0
    ? Math.max(...produtos.map(p => p.codigo)) + 1
        : 1;

        // 1. Salvar produtos no navegador
        function salvarProdutos() {
            localStorage.setItem("produtos", JSON.stringify(produtos));
            }

            // 2. Validar os dados do produto
            function validarProduto(descricao, quantidade, valor) {
                if (descricao.trim() === "") {
                        return "A descrição não pode ficar vazia.";
                            }

                                if (quantidade <= 0 || !Number.isInteger(quantidade)) {
                                        return "A quantidade deve ser um número inteiro maior que zero.";
                                            }

                                                if (valor <= 0 || !Number.isFinite(valor)) {
                                                        return "O valor deve ser maior que zero.";
                                                            }

                                                                return "";
                                                                }

                                                                // 3. Cadastrar produto
                                                                function cadastrarProduto(event) {
                                                                    event.preventDefault();

                                                                        const descricao = document.getElementById("descricao").value;
                                                                            const quantidade = Number(
                                                                                    document.getElementById("quantidade").value
                                                                                        );
                                                                                            const valor = Number(
                                                                                                    document.getElementById("valor").value
                                                                                                        );

                                                                                                            const erro = validarProduto(descricao, quantidade, valor);

                                                                                                                if (erro !== "") {
                                                                                                                        mostrarMensagem(erro, "red");
                                                                                                                                return;
                                                                                                                                    }

                                                                                                                                        // Criando o objeto produto
                                                                                                                                            const produto = {
                                                                                                                                                    codigo: proximoCodigo,
                                                                                                                                                            descricao: descricao.trim(),
                                                                                                                                                                    quantidade: quantidade,
                                                                                                                                                                            valor: valor
                                                                                                                                                                                };

                                                                                                                                                                                    // Adicionando produto ao array
                                                                                                                                                                                        produtos.push(produto);

                                                                                                                                                                                            proximoCodigo++;

                                                                                                                                                                                                salvarProdutos();
                                                                                                                                                                                                    listarProdutos();

                                                                                                                                                                                                        document.getElementById("formProduto").reset();

                                                                                                                                                                                                            mostrarMensagem("Produto cadastrado com sucesso!", "green");
                                                                                                                                                                                                            }

                                                                                                                                                                                                            // 4. Listar produtos
                                                                                                                                                                                                            function listarProdutos(lista = produtos) {
                                                                                                                                                                                                                const tabela = document.getElementById("listaProdutos");

                                                                                                                                                                                                                    tabela.innerHTML = "";

                                                                                                                                                                                                                        if (lista.length === 0) {
                                                                                                                                                                                                                                tabela.innerHTML = `
                                                                                                                                                                                                                                            <tr>
                                                                                                                                                                                                                                                            <td colspan="5">Nenhum produto encontrado.</td>
                                                                                                                                                                                                                                                                        </tr>
                                                                                                                                                                                                                                                                                `;
                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                lista.forEach(produto => {
                                                                                                                                                                                                                                                                                                        const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                const codigo = document.createElement("td");
                                                                                                                                                                                                                                                                                                                        codigo.textContent = produto.codigo;

                                                                                                                                                                                                                                                                                                                                const descricao = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                        descricao.textContent = produto.descricao;

                                                                                                                                                                                                                                                                                                                                                const quantidade = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                        quantidade.textContent = produto.quantidade;

                                                                                                                                                                                                                                                                                                                                                                const valor = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                        valor.textContent = produto.valor.toLocaleString(
                                                                                                                                                                                                                                                                                                                                                                                    "pt-BR",
                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                style: "currency",
                                                                                                                                                                                                                                                                                                                                                                                                                                currency: "BRL"
                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                            const acoes = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    acoes.className = "acoes";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const botaoValor = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botaoValor.textContent = "Alterar Valor";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botaoValor.onclick = () => atualizarValor(produto.codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const botaoEstoque = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botaoEstoque.textContent = "Somar Estoque";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botaoEstoque.onclick = () => atualizarQuantidade(produto.codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const botaoExcluir = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botaoExcluir.textContent = "Excluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botaoExcluir.onclick = () => excluirProduto(produto.codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    acoes.append(botaoValor, botaoEstoque, botaoExcluir);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            linha.append(codigo, descricao, quantidade, valor, acoes);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tabela.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 5. Buscar produto usando find()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function buscarProduto() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const codigo = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("codigoBusca").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!Number.isInteger(codigo) || codigo <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem("Digite um código válido.", "red");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const produto = produtos.find(p => p.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarProdutos([]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mostrarMensagem("Produto não encontrado.", "red");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos([produto]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarMensagem("Produto encontrado!", "green");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 6. Atualizar valor do produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function atualizarValor(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const produto = produtos.find(p => p.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarMensagem("Produto não encontrado.", "red");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const novoValor = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    prompt("Digite o novo valor do produto:")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!Number.isFinite(novoValor) || novoValor <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem("Digite um valor válido.", "red");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.valor = novoValor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarMensagem("Valor atualizado!", "green");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 7. Atualizar quantidade do produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function atualizarQuantidade(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const produto = produtos.find(p => p.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarMensagem("Produto não encontrado.", "red");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const quantidadeAdicionar = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        prompt("Quantas unidades deseja adicionar?")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        !Number.isInteger(quantidadeAdicionar) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                quantidadeAdicionar <= 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarMensagem("Digite uma quantidade válida.", "red");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Soma a quantidade ao estoque existente
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produto.quantidade += quantidadeAdicionar;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarMensagem("Estoque atualizado!", "green");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 8. Excluir produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function excluirProduto(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const produto = produtos.find(p => p.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarMensagem("Produto não encontrado.", "red");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const confirmar = confirm(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Deseja excluir o produto " + produto.descricao + "?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!confirmar) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produtos = produtos.filter(p => p.codigo !== codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mostrarMensagem("Produto excluído!", "green");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 9. Mostrar mensagens
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function mostrarMensagem(texto, cor) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const mensagem = document.getElementById("mensagem");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagem.textContent = texto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagem.style.color = cor;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Evento do formulário
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("formProduto")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .addEventListener("submit", cadastrarProduto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Mostrar os produtos ao abrir a página
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        